const trig = $('Sub-workflow Input').first()?.json || {};
const ctx = $('Resolve Tenant Context').first()?.json || {};
const scope = String(trig.scope || 'onedrive').toLowerCase();
const limit = Math.min(parseInt(trig.limit, 10) || 10, 50);
const recordId = String(trig.recordId || '').trim();
const query = String(trig.query || '').trim();
const orgCfg = (ctx.orgConfig && typeof ctx.orgConfig === 'object') ? ctx.orgConfig : {};
const fbCfg = (trig.fallbackOrgConfig && typeof trig.fallbackOrgConfig === 'object') ? trig.fallbackOrgConfig : {};
const cfg = Object.assign({}, fbCfg, orgCfg);
const envelope = {
  ok: false, status: 'refused', reasonCode: 'none', guidance: 'none', userMessage: null,
  connectorId: 'microsoft.sharepoint', organizationId: ctx.organizationId || null, userId: ctx.userId || null,
  contextSource: ctx.contextSource || 'fallback', degraded: ctx.degraded === true,
  records: [], total: 0, error: null,
  diagnostics: { requestId: 'spd-' + ($execution.id || 'na') + '-' + Date.now(), workflow: 'prism-11-sharepoint-service', scope: scope }
};
function refuse(code, msg, guidance) { envelope.status = 'refused'; envelope.reasonCode = code; envelope.userMessage = msg; envelope.guidance = guidance; return [{ json: envelope }]; }
if (ctx.enabled === false) return refuse('connector_disabled', 'SharePoint & OneDrive is turned off for you - enable it in Connections.', 'enable');
if (ctx.entitlement === false) return refuse('not_entitled', 'Your account does not have access to SharePoint & OneDrive - ask your admin to unlock it.', 'request_access');
if (!ctx.accessToken) return refuse('missing_token', 'SharePoint & OneDrive is not connected yet - connect your account in Connections to get started.', 'connect');
let url = '';
if (scope === 'sites' || scope === 'sites_list' || scope === 'allsites') {
  // List/search SharePoint sites. No site ID required.
  url = 'https://graph.microsoft.com/v1.0/sites?search=' + encodeURIComponent(query || '*') + '&$top=' + limit + '&$select=id,name,displayName,webUrl,createdDateTime,lastModifiedDateTime';
} else if (scope === 'site' || scope === 'sitelibrary' || scope === 'sitelibraries') {
  if (recordId) {
    // Browse a specific site's drives/libraries
    url = 'https://graph.microsoft.com/v1.0/sites/' + encodeURIComponent(recordId) + '/drives?$top=' + limit + '&$select=id,name,driveType,webUrl,lastModifiedDateTime';
  } else {
    const siteId = String(cfg.sharepointSiteId || '').trim();
    if (!siteId || siteId === 'root') return refuse('empty', 'Tell me which SharePoint site to browse (or set a default site in organization settings) - I can also list all sites if you ask.', 'none');
    url = 'https://graph.microsoft.com/v1.0/sites/' + encodeURIComponent(siteId) + '/drive/root/children?$top=' + limit + '&$select=id,name,folder,file,lastModifiedDateTime,webUrl,size';
  }
} else {
  if (recordId) url = 'https://graph.microsoft.com/v1.0/me/drive/items/' + encodeURIComponent(recordId) + '/children?$top=' + limit + '&$select=id,name,folder,file,lastModifiedDateTime,webUrl,size';
  else url = 'https://graph.microsoft.com/v1.0/me/drive/root/children?$top=' + limit + '&$select=id,name,folder,file,lastModifiedDateTime,webUrl,size';
}
return [{ json: Object.assign({}, envelope, { ok: true, status: 'pending', accessToken: ctx.accessToken, requestUrl: url, scopeType: (scope === 'sites' || scope === 'sites_list' || scope === 'allsites') ? 'sites' : (scope === 'site' || scope === 'sitelibrary' || scope === 'sitelibraries') ? 'sitelibraries' : 'onedrive' }) }];

const res = $input.first()?.json || {};
const meta = $('Gate & Build Request').first()?.json || {};
const scopeType = meta.scopeType || 'onedrive';
const envelope = {
  ok: false, status: 'error', reasonCode: 'provider_error', guidance: 'retry',
  userMessage: 'SharePoint & OneDrive returned an error - try again shortly. If it persists, check the connection in Connections.',
  connectorId: 'microsoft.sharepoint', organizationId: meta.organizationId || null, userId: meta.userId || null,
  contextSource: meta.contextSource || 'fallback', degraded: meta.degraded === true,
  records: [], total: 0, error: null,
  diagnostics: { requestId: (meta.diagnostics && meta.diagnostics.requestId) || ('spd-' + Date.now()), workflow: 'prism-11-sharepoint-service', scope: (meta.diagnostics && meta.diagnostics.scope) || 'unknown' }
};
const httpStatus = (res.error && (res.error.status || res.error.statusCode)) || res.statusCode || null;
const errCode = res.error && res.error.code ? String(res.error.code) : '';
function finishSuccess() { envelope.ok = true; envelope.status = 'success'; envelope.reasonCode = 'none'; envelope.guidance = 'none'; envelope.userMessage = null; envelope.error = null; }
if (httpStatus === 401 || errCode === 'InvalidAuthenticationToken') { envelope.reasonCode = 'reauth_required'; envelope.guidance = 'reconnect'; envelope.userMessage = 'Your Microsoft connection needs re-authentication - reconnect in Connections.'; envelope.error = { provider: 'microsoft', httpStatus: 401, message: errCode || 'unauthorized', retryable: false }; return [{ json: envelope }]; }
if (httpStatus === 403) { envelope.reasonCode = 'not_entitled'; envelope.guidance = 'request_access'; envelope.userMessage = 'The Microsoft connection does not have permission for this ' + scopeType + ' read - check the granted scopes in Connections.'; envelope.error = { provider: 'microsoft', httpStatus: 403, message: errCode || 'forbidden', retryable: false }; return [{ json: envelope }]; }
const raw = Array.isArray(res.value) ? res.value : [];
const records = raw.map(function (d) {
  if (scopeType === 'sites') return { id: String(d.id || ''), name: d.displayName || d.name || '', webUrl: d.webUrl || '', created: d.createdDateTime || '', lastModified: d.lastModifiedDateTime || '' };
  if (scopeType === 'sitelibraries') return { id: String(d.id || ''), name: d.name || '', driveType: d.driveType || '', webUrl: d.webUrl || '', lastModified: d.lastModifiedDateTime || '' };
  return { id: String(d.id || ''), name: d.name || '', isFolder: !!(d.folder), isFile: !!(d.file), size: d.size != null ? Number(d.size) : 0, lastModified: d.lastModifiedDateTime || '', webUrl: d.webUrl || '' };
});
finishSuccess(); envelope.records = records; envelope.total = records.length;
return [{ json: envelope }];
